UPDATE tipos_actividad
SET nombre = CASE HEX(nombre)
  WHEN '4C6576616E74616D69656E746F207920446961676EE2949CE29482737469636F' THEN CONVERT(0x4C6576616E74616D69656E746F207920446961676EC3B3737469636F USING utf8mb4)
  WHEN '456A6563756369E2949CE294826E20792050726F636573616D69656E746F204F706572617469766F' THEN CONVERT(0x456A6563756369C3B36E20792050726F636573616D69656E746F204F706572617469766F USING utf8mb4)
  WHEN '416EE2949CC3AD6C697369732C204D6170656F207920456C61626F72616369E2949CE294826E' THEN CONVERT(0x416EC3A16C697369732C204D6170656F207920456C61626F72616369C3B36E USING utf8mb4)
  WHEN '526576697369E2949CE294826E2C20496E666F726D6573207920436965727265' THEN CONVERT(0x526576697369C3B36E2C20496E666F726D6573207920436965727265 USING utf8mb4)
  WHEN '4765737469E2949CE294826E20496E7465726E612079204361706163746963616369E2949CE294826E' THEN CONVERT(0x4765737469C3B36E20496E7465726E6120792043617061636974616369C3B36E USING utf8mb4)
  ELSE nombre
END
WHERE id > 0
  AND es_general = TRUE
  AND HEX(nombre) IN (
    '4C6576616E74616D69656E746F207920446961676EE2949CE29482737469636F',
    '456A6563756369E2949CE294826E20792050726F636573616D69656E746F204F706572617469766F',
    '416EE2949CC3AD6C697369732C204D6170656F207920456C61626F72616369E2949CE294826E',
    '526576697369E2949CE294826E2C20496E666F726D6573207920436965727265',
    '4765737469E2949CE294826E20496E7465726E612079204361706163746963616369E2949CE294826E'
  );

SELECT id, nombre, HEX(nombre)
FROM tipos_actividad
WHERE es_general = TRUE
ORDER BY id;
